<?php
namespace App\Http\Controllers;
use App\Repositories\ClienteRepository;use App\Services\{ClienteService,AuditoriaService};use Illuminate\Http\Request;use Illuminate\Support\Str;
class ClienteController extends Controller { public function __construct(private ClienteRepository $repo,private ClienteService $service,private AuditoriaService $audit){} public function index(Request $r){$q=strtolower($r->get('q',''));$clients=collect($this->repo->where('loja_id',session('loja_id')))->filter(fn($c)=>!$q||str_contains(strtolower(($c['nome']??'').' '.($c['apelido']??'').' '.($c['telefone']??'')),$q));return view('clients.index',compact('clients','q'));} public function create(){return view('clients.form',['cliente'=>null]);} public function store(Request $r){$d=$this->validated($r);$d['loja_id']=session('loja_id');$d['token_consulta']=Str::random(40);$d['status']=$d['status']??'ativo';$c=$this->repo->create($d);$this->audit->log('Cliente cadastrado','cliente',$c['id'],$c['nome']);return redirect()->route('clients.show',$c['id'])->with('success','Cliente cadastrado com sucesso.');} public function show(string $id){$cliente=$this->service->owned($id);abort_unless($cliente,404);return view('clients.show',$this->service->detail($cliente));} public function edit(string $id){$cliente=$this->service->owned($id);abort_unless($cliente,404);return view('clients.form',compact('cliente'));} public function update(Request $r,string $id){$c=$this->service->owned($id);abort_unless($c,404);$this->repo->update($id,$this->validated($r));$this->audit->log('Cliente editado','cliente',$id,$c['nome']);return redirect()->route('clients.show',$id)->with('success','Cliente atualizado.');} public function block(string $id){$c=$this->service->owned($id);abort_unless($c,404);$this->repo->update($id,['status'=>'bloqueado','motivo_bloqueio'=>request('motivo','Bloqueado manualmente')]);$this->audit->log('Cliente bloqueado','cliente',$id,$c['nome']);return back()->with('success','Cliente bloqueado.');} private function validated(Request $r):array{return $r->validate(['nome'=>'required|max:120','apelido'=>'nullable|max:80','telefone'=>'nullable|max:20','endereco'=>'nullable|max:255','referencia'=>'nullable|max:255','cpf'=>'nullable|max:20','limite_fiado'=>'required|numeric|min:0','dia_preferido_pagamento'=>'nullable|integer|min:1|max:31','observacoes'=>'nullable|max:1000','status'=>'nullable|in:ativo,bloqueado,inativo']);} }
